function e(e,t=`RUB`,n=`ru-RU`){if(e==null)return``;try{return new Intl.NumberFormat(n,{style:`currency`,currency:t,maximumFractionDigits:2}).format(e)}catch{return`${Number(e).toFixed(2)} ${t}`}}function t(e,t=`Europe/Moscow`,n=`ru-RU`){if(!e)return``;let r=new Date(e*1e3);return new Intl.DateTimeFormat(n,{timeZone:t,year:`numeric`,month:`2-digit`,day:`2-digit`}).format(r)}function n(e,t=`Europe/Moscow`,n=`ru-RU`){if(!e)return``;let r=new Date(e*1e3);return new Intl.DateTimeFormat(n,{timeZone:t,hour:`2-digit`,minute:`2-digit`}).format(r)}function r(e){if(!e||e<0)return`0с`;let t=Math.floor(e),n=Math.floor(t/3600),r=Math.floor(t%3600/60),i=t%60;return n>0?`${n}ч ${r}м`:r>0?`${r}м ${i}с`:`${i}с`}export{n as i,r as n,e as r,t};